-- ccb34b9d | ما حكم صيام رمضان؟
UPDATE qa_questions SET
  answer = 'صيامُ شهر رمضان فرضٌ ثابتٌ بالكتاب والسنّة، وهو أحدُ مباني الإسلام الخمسة: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ … وَصَوْمِ رَمَضَانَ» (البخاري ٨)، وأصلُه من الكتاب ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ﴾ [البقرة: ١٨٣]، والمفروضُ منه شهرٌ واحدٌ لا غير: «شَهْرَ رَمَضَانَ إِلَّا أَنْ تَطَّوَّعَ شَيْئًا» (البخاري ١٨٩١). ⚠️ وقيدُ ‹مقيم› في الجواب السابق موهِمٌ يُصحَّح: المسافرُ مخاطَبٌ بالصوم غيرُ ساقطٍ عنه، وإنما رُخِّص له في تأخيره مع القضاء ﴿فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ﴾ [البقرة: ١٨٤] — فهي رخصةُ تأجيلٍ لا إسقاطُ فرضٍ، ومثلُه المريض. وأمّا ‹قادر› فبيانُه في الكتاب: من لا يُطيقه فعليه الفديةُ ﴿وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌۭ طَعَامُ مِسْكِينٍۢ﴾ [البقرة: ١٨٤]. وأمّا ‹بالغ عاقل› فمستنَدُه رفعُ القلم: «أَنَّ الْقَلَمَ رُفِعَ عَنْ ثَلَاثَةٍ عَنِ الْمَجْنُونِ حَتَّى يُفِيقَ وَعَنِ الصَّبِيِّ حَتَّى يُدْرِكَ وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ» — وهو عند البخاري **أثرٌ عن عليٍّ معلَّقًا** في ترجمة الباب (ج٧/ص٤٥) لا حديثٌ مسنَد، فيُنسب على وجهه.',
  reference = 'صحيح البخاري (ط السلطانية): ٨ (ج١/ص١١، كتاب الإيمان) و٤٦ (ج١/ص١٨، باب الزكاة من الإسلام) و١٨٩١ (ج٣/ص٢٤، كتاب الصوم، باب وجوب صوم رمضان) وتعليقُ أثر عليّ في ترجمة باب الطلاق في الإغلاق (ج٧/ص٤٥)؛ ومصحفُ المشروع: البقرة ١٨٣–١٨٥ | الكلمات المفتاحية: رمضان، صيام، فرض',
  evidence = 'صومُ رمضان أحدُ مباني الإسلام في حديث ابن عمر عند البخاري ٨ (ج١/ص١١، كتاب الإيمان): «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ». وترجم له البخاري في ج٣/ص٢٤: «بَابُ وُجُوبِ صَوْمِ رَمَضَانَ وَقَوْلِ اللهِ تَعَالَى» ثم ساق قولَه سبحانه ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ﴾ [البقرة: ١٨٣]. وقدرُ المفروض شهرٌ واحدٌ لا يزيد: «أَخْبِرْنِي مَا فَرَضَ اللهُ عَلَيَّ مِنَ الصِّيَامِ؟ فَقَالَ: شَهْرَ رَمَضَانَ إِلَّا أَنْ تَطَّوَّعَ شَيْئًا» (البخاري ١٨٩١، ج٣/ص٢٤)، وفي حديث طلحة نفسِه عند البخاري ٤٦ (ج١/ص١٨): «وَصِيَامُ رَمَضَانَ. قَالَ: هَلْ عَلَيَّ غَيْرُهُ؟ قَالَ: لَا، إِلَّا أَنْ تَطَوَّعَ». وأمّا مَن يُخاطَب به فأثرُ عليٍّ **معلَّقًا** عند البخاري في ترجمة باب الطلاق في الإغلاق (ج٧/ص٤٥): «أَلَمْ تَعْلَمْ أَنَّ الْقَلَمَ رُفِعَ عَنْ ثَلَاثَةٍ عَنِ الْمَجْنُونِ حَتَّى يُفِيقَ وَعَنِ الصَّبِيِّ حَتَّى يُدْرِكَ وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ». وأمّا المريضُ والمسافر فنصُّ الكتاب فيهما ﴿فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ﴾ [البقرة: ١٨٤]، ومثلُه ﴿فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ﴾ [البقرة: ١٨٥]، وللعاجز عنه ﴿وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌۭ طَعَامُ مِسْكِينٍۢ﴾ [البقرة: ١٨٤].',
  verification_status = 'verified'
WHERE id = 'ccb34b9d-7cd7-4ce3-84ef-bbd09bb6e12f'
  AND reference = 'القرآن الكريم؛ صحيح البخاري | الكلمات المفتاحية: رمضان، صيام، فرض'
  AND evidence = 'قال تعالى: ﴿كُتِبَ عَلَيْكُمُ الصِّيَامُ﴾ [البقرة: 183].'
  AND answer = 'صيام رمضان فرض على كل مسلم بالغ عاقل قادر مقيم.';

-- ff33cb6f | ما فضل طلب العلم الشرعي؟
UPDATE qa_questions SET
  answer = 'طلبُ العلم الشرعيّ سببٌ مُيسِّرٌ لطريق الجنّة بنصّ حديث أبي هريرة: «ومن سلك طريقا يلتمس فيه علما، سهل الله له به طريقا إلى الجنة» (مسلم ٢٦٩٩)، وأجرُه لا ينقطع بموت صاحبه: «إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ … أَوْ عِلْمٍ يُنْتَفَعُ بِهِ» (مسلم ١٦٣١). ⚠️ ولفظُ ‹لا يستوي عند الله من يعلم ومن لا يعلم› في الجواب السابق **صياغةٌ لا لفظُ آية**، وإنما نصُّها استفهامُ إنكارٍ يُنقَل بحروفه: ﴿قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ﴾ [الزمر: ٩]. ورفعةُ أهله منصوصةٌ ﴿يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍۢ﴾ [المجادلة: ١١]، وثمرتُه الخشيةُ ﴿إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟﴾ [فاطر: ٢٨]، ولم يُؤمَر النبيُّ ﷺ بالاستزادة من شيءٍ إلا منه ﴿وَقُل رَّبِّ زِدْنِى عِلْمًۭا﴾ [طه: ١١٤]. وموضعُ الحديث من صحيح مسلم بابُ فضل الاجتماع على تلاوة القرآن وعلى الذكر (ج٤/ص٢٠٧٤)، وهو طرفٌ من حديثٍ أوّلُه «من نفس عن مؤمن كربة من كرب الدنيا».',
  reference = 'صحيح مسلم (ت محمد فؤاد عبد الباقي): ٢٦٩٩ (ج٤/ص٢٠٧٤، باب فضل الاجتماع على تلاوة القرآن وعلى الذكر) و١٦٣١ (ج٣/ص١٢٥٥، باب ما يلحق الإنسان من الثواب بعد وفاته)؛ ومصحفُ المشروع: الزمر ٩، المجادلة ١١، فاطر ٢٨، طه ١١٤ | الكلمات المفتاحية: فضل العلم، طلب العلم',
  evidence = 'الحديثُ الذي احتجَّ به الجوابُ ثابتٌ عند مسلم ٢٦٩٩ (ج٤/ص٢٠٧٤، باب فضل الاجتماع على تلاوة القرآن وعلى الذكر) في سياقٍ أطول من حديث أبي هريرة: «ومن سلك طريقا يلتمس فيه علما، سهل الله له به طريقا إلى الجنة. وما اجتمع قوم في بيت من بيوت الله، يتلون كتاب الله، ويتدارسونه بينهم، إلا نزلت عليهم السكينة، وغشيتهم الرحمة وحفتهم الملائكة، وذكرهم الله فيمن عنده». وأجرُ العلم باقٍ بعد الموت عند مسلم ١٦٣١ (ج٣/ص١٢٥٥، باب ما يلحق الإنسان من الثواب بعد وفاته): «إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ: إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ. أَوْ عِلْمٍ يُنْتَفَعُ بِهِ. أو ولد صالح يدعو له». وأمّا الكتابُ فقولُه تعالى ﴿قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ﴾ [الزمر: ٩]، و﴿يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍۢ﴾ [المجادلة: ١١]، و﴿إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟﴾ [فاطر: ٢٨]، و﴿وَقُل رَّبِّ زِدْنِى عِلْمًۭا﴾ [طه: ١١٤].',
  verification_status = 'verified'
WHERE id = 'ff33cb6f-5438-4717-ab67-7a83cfe4c85e'
  AND reference = 'القرآن الكريم؛ صحيح مسلم | الكلمات المفتاحية: فضل العلم، طلب العلم'
  AND evidence = 'قال تعالى: ﴿قُلْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ﴾ [الزمر: ٩]. وقال النبي ﷺ: «من سلك طريقًا يلتمس فيه علمًا سهّل الله له به طريقًا إلى الجنة» رواه مسلم.'
  AND answer = 'طلب العلم طريق موصل للجنة ييسّر الله لسالكه طريقًا إليها، ولا يستوي عند الله من يعلم ومن لا يعلم.';

-- 69e6b7b0 | هل الوضوء شرط لصحة الصلاة؟
UPDATE qa_questions SET
  answer = 'نعم، لا تصحُّ الصلاةُ بغير طهارةٍ: «لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ» (مسلم ٢٢٤)، وترجم له مسلمٌ ببابِ وجوب الطهارة للصلاة (ج١/ص٢٠٤)، ومناطُ انتقاضها الحدثُ: «لَا تُقْبَلُ صَلَاةُ أَحَدِكُمْ، إِذَا أَحْدَثَ، حَتَّى يتوضأ» (مسلم ٢٢٥). ⚠️ والشرطُ ‹الطهارة› لا ‹الوضوء› وحدَه كما في صيغة السؤال: لفظُ الحديث «بِغَيْرِ طُهُورٍ» يعمُّ الوضوءَ من الحدث الأصغر، والغُسلَ من الجنابة ﴿وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟﴾، والتيمُّمَ عند فقد الماء ﴿فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا﴾ [المائدة: ٦]. فقيدُ ‹عند القدرة› في الجواب السابق يُبيَّن على وجهه: العاجزُ عن الماء لا يسقط عنه الشرطُ، بل ينتقل إلى بدلِه المنصوص، لا أن يصلّيَ بلا طَهُور.',
  reference = 'صحيح مسلم (ت محمد فؤاد عبد الباقي): ٢٢٤ و٢٢٥ (ج١/ص٢٠٤، باب وجوب الطهارة للصلاة)؛ ومصحفُ المشروع: المائدة ٦ | الكلمات المفتاحية: وضوء، طهارة، صلاة',
  evidence = 'عقد مسلمٌ لهذا بابَ وجوب الطهارة للصلاة (ج١/ص٢٠٤)، وفيه حديثُ ابن عمر ٢٢٤: «لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ. وَلَا صَدَقَةٌ مِنْ غُلُولٍ»، وحديثُ أبي هريرة ٢٢٥ في الموضع نفسِه: «لَا تُقْبَلُ صَلَاةُ أَحَدِكُمْ، إِذَا أَحْدَثَ، حَتَّى يتوضأ». وأصلُه من الكتاب ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ﴾، وفي الآية نفسِها أن موجَبَ الجنابة الاغتسالُ ﴿وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟﴾، وأن بدلَ الماء عند فقده التيمُّمُ ﴿فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ﴾ [المائدة: ٦].',
  verification_status = 'verified'
WHERE id = '69e6b7b0-db1e-435f-91d0-9c567bd862c9'
  AND reference = 'القرآن الكريم؛ صحيح مسلم | الكلمات المفتاحية: وضوء، طهارة، صلاة'
  AND evidence = 'قال تعالى: ﴿إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ﴾ [المائدة: 6].'
  AND answer = 'نعم، الطهارة شرط لصحة الصلاة عند القدرة.';
